INSERT INTO material_translations (material_id, locale, title, description, body) VALUES ('ddd52d50-62ae-4a6c-a4ca-ec7005fb4f7f','ro','Universul (partea I) — galerie foto','Imagini care ilustrează lecția: Big Bang, Calea Lactee, nebuloase, evoluția și culoarea stelelor și tipurile de galaxii.','{"captions":["Teoria Big Bang și expansiunea Universului","Calea Lactee, galaxia noastră, văzută din față și din profil","Brațele Căii Lactee și poziția Soarelui (brațul Orion)","Calea Lactee ca brâu luminos pe cerul nopții","Nebuloasa Vulturul (Eagle) — „Stâlpii Creației”, în lumină vizibilă și în infraroșu","Evoluția stelelor în funcție de masă","Legătura dintre temperatura și culoarea stelelor","Tipuri de galaxii după formă"]}');
